/**
 * ProductForm Component Tests
 *
 * Tests for product form validation, submission, and interaction.
 * This file tests both new product creation and product editing flows,
 * including validation, error handling, price management, and form submission.
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { screen, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { render } from '@/__tests__/utils/test-utils'
import {
  createMockProduct,
  createMockCategory,
  createMockCurrentPrice,
