          const queryBuilder = {
            select: vi.fn(() => queryBuilder),
            eq: vi.fn(() => queryBuilder),
            order: vi.fn(() => queryBuilder),
            then: vi.fn((callback) => {
              return Promise.resolve({
                data: config.selectData,
                error: null,
